test-case.test:
(: 3 Full-Text Selections: Test valid weight value (within negative part of range) :)
declare variable $input-context external;
<paragraphs>
{ for $p score $sc in $input-context//div2[@id="id-minimal-conformance"]//p
where $p contains text "everything" weight {-100.0}
order by $sc
return $p }
</paragraphs>

(: 3 Full-Text Selections: Test valid weight value (at high negative end of range) :)
declare variable $input-context external;
<paragraphs>
{ for $p score $sc in $input-context//div2[@id="id-minimal-conformance"]//p
where $p contains text "everything" weight {-1000.0}
order by $sc
return $p }
</paragraphs>

(: 3 Full-Text Selections: Test valid weight value (within negative part of range) :)
declare variable $input-context external;
declare variable $weight-1 := -100;
<paragraphs>
{ for $p score $sc in $input-context//div2[@id="id-minimal-conformance"]//p
where $p contains text "everything" weight {$weight-1}
order by $sc
return $p }
</paragraphs>

(: 3 Full-Text Selections: Test valid weight value (within negative part of range) :)
declare variable $input-context external;
declare variable $weight-1 := -1000;
<paragraphs>
{ for $p score $sc in $input-context//div2[@id="id-minimal-conformance"]//p
where $p contains text "everything" weight {$weight-1}
order by $sc
return $p }
</paragraphs>

(: 3 Full-Text Selections: Test valid weight value (within negative part of range) :)
declare variable $input-context external;
declare variable $weight-1 := -100;
declare variable $weight-2 := -500;
<paragraphs>
{ for $p score $sc in $input-context//div2[@id="id-minimal-conformance"]//p
where $p contains text "everything" weight {$weight-1 + $weight-2}
order by $sc
return $p }
</paragraphs>
